#include <bits/stdc++.h>
using namespace std;

int digitsBase7(long long x) {
    int digits = 1;
    while (x >= 7) {
        x /= 7;
        ++digits;
    }
    return digits;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    if (n <= 0 || m <= 0) {
        cout << 0;
        return 0;
    }

    int hourDigits = digitsBase7(n - 1);
    int minuteDigits = digitsBase7(m - 1);

    if (hourDigits + minuteDigits > 7) {
        cout << 0;
        return 0;
    }

    long long answer = 0;

    for (long long hour = 0; hour < n; ++hour) {
        for (long long minute = 0; minute < m; ++minute) {
            bool used[7] = {};
            bool valid = true;

            long long value = hour;
            for (int i = 0; i < hourDigits; ++i) {
                int digit = value % 7;
                value /= 7;

                if (used[digit]) {
                    valid = false;
                    break;
                }
                used[digit] = true;
            }

            if (!valid) continue;

            value = minute;
            for (int i = 0; i < minuteDigits; ++i) {
                int digit = value % 7;
                value /= 7;

                if (used[digit]) {
                    valid = false;
                    break;
                }
                used[digit] = true;
            }

            if (valid) ++answer;
        }
    }

    cout << answer;
    return 0;
}

