    int hDigits = digitsBase7(h - 1);
    int mDigits = digitsBase7(m - 1);

    if (hDigits + mDigits > 7) {
        cout << 0;
        return 0;
    }

    long long answer = 0;

    function<void(int, int, long long, long long)> dfs =
        [&](int position, int used, long long hour, long long minute) {
            if (position == hDigits + mDigits) {
                if (hour < h && minute < m)
                    ++answer;
                return;
            }

            for (int digit = 0; digit < 7; ++digit) {
                if (used & (1 << digit))
                    continue;

                if (position < hDigits) {
                    dfs(position + 1, used | (1 << digit),
                        hour * 7 + digit, minute);
                } else {
                    dfs(position + 1, used | (1 << digit),
                        hour, minute * 7 + digit);
                }
            }
        };

    dfs(0, 0, 0, 0);
    cout << answer;

    return 0;
}

