using namespace std;

int digitsBase7(long long value) {
    int digits = 1;
    while (value >= 7) {
        value /= 7;
        ++digits;
    }
    return digits;
}

bool hasUniqueDigits(long long hour, long long minute, int hourDigits, int minuteDigits) {
    bool used[7] = {};

    for (int i = 0; i < hourDigits; ++i) {
        int digit = hour % 7;
        hour /= 7;
        if (used[digit]) return false;
        used[digit] = true;
    }

    for (int i = 0; i < minuteDigits; ++i) {
        int digit = minute % 7;
        minute /= 7;
        if (used[digit]) return false;
        used[digit] = true;
    }

    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h, m;
    cin >> h >> m;

    if (h <= 0 || m <= 0) {
        cout << 0;
        return 0;
    }

    int hourDigits = digitsBase7(h - 1);
    int minuteDigits = digitsBase7(m - 1);

    if (hourDigits + minuteDigits > 7) {
        cout << 0;
        return 0;
    }

    long long result = 0;

    for (long long hour = 0; hour < h; ++hour) {
        for (long long minute = 0; minute < m; ++minute) {
            result += hasUniqueDigits(hour, minute, hourDigits, minuteDigits);
        }
    }

    cout << result;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int digits_base7(long long x) {
    int digits = 1;
    while (x >= 7) {
        x /= 7;
        ++digits;
    }
    return digits;
}

bool add_digits(long long value, int width, int& mask) {
    for (int i = 0; i < width; ++i) {
        int digit = value % 7;
        value /= 7;

        if (mask & (1 << digit)) return false;
        mask |= 1 << digit;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h, m;
    cin >> h >> m;

    if (h <= 0 || m <= 0) {
        cout << 0;
        return 0;
    }

    int hourDigits = digits_base7(h - 1);
    int minuteDigits = digits_base7(m - 1);

    if (hourDigits + minuteDigits > 7) {
        cout << 0;
        return 0;
    }

    long long answer = 0;

    for (long long hour = 0; hour < h; ++hour) {
        int hourMask = 0;
        if (!add_digits(hour, hourDigits, hourMask)) continue;

        for (long long minute = 0; minute < m; ++minute) {
            int mask = hourMask;
            if (add_digits(minute, minuteDigits, mask)) {
                ++answer;
            }
        }
    }

    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int64 h, m, answer = 0;
int hourDigits, minuteDigits;

int digitsBase7(int64 value) {
    int digits = 1;
    while (value >= 7) {
        value /= 7;
        ++digits;
    }
    return digits;
}

void dfs(int position, int totalDigits, int64 hourValue,
         int64 minuteValue, int usedMask) {
    if (position == totalDigits) {
        if (hourValue < h && minuteValue < m) {
            ++answer;
        }
        return;
    }

    for (int digit = 0; digit < 7; ++digit) {
        if (usedMask & (1 << digit)) continue;

        if (position < hourDigits) {
            dfs(position + 1, totalDigits,
                hourValue * 7 + digit, minuteValue,
                usedMask | (1 << digit));
        } else {
            dfs(position + 1, totalDigits,
                hourValue, minuteValue * 7 + digit,
                usedMask | (1 << digit));
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> h >> m;

    if (h <= 0 || m <= 0) {
        cout << 0;
        return 0;
    }

    hourDigits = digitsBase7(h - 1);
    minuteDigits = digitsBase7(m - 1);

    if (hourDigits + minuteDigits > 7) {
        cout << 0;
        return 0;
    }

    dfs(0, hourDigits + minuteDigits, 0, 0, 0);
    cout << answer;

    return 0;
}

